export function wallTop(map,w){const [[x,z],[x2,z2]]=w.points,mx=(x+x2)/2,mz=(z+z2)/2,len=Math.hypot(x2-x,z2-z)||1,nx=-(z2-z)/len*.35,nz=(x2-x)/len*.35;let top=0;for(const [px,pz]of [[mx+nx,mz+nz],[mx-nx,mz-nz]]){const c=ceilingAt(map,px,pz);if(c?.ft!=null)top=Math.max(top,c.ft/5);}return top||1.85;}
