 const pulse=.78+.22*Math.sin(time*2.1),vol=[...color,(e.lasting?(e.darkness?.62:.3):.13)*pulse],seg=detail>=10?18:8;if(e.shape==='circle')domeMesh(out,x,z,e.radius_ft/5,vol,seg);else if(e.shape==='melee')domeMesh(out,x,z,.5,[...color,.3*pulse],seg,.9);else if(e.shape==='cone')coneSolidMesh(out,[x,.9,z],dir,l,l/2,vol,seg);else if(e.shape==='line')prismMesh(out,[point(0,-w/2),point(l,-w/2),point(l,w/2),point(0,w/2)],.02,Math.max(.4,w),vol);else if(e.shape==='rectangle')prismMesh(out,[point(0,-w/2),point(l,-w/2),point(l,w/2),point(0,w/2)],.02,e.height_ft?e.height_ft/5:(w<=1.2?2.2:.9),vol);else if(e.shape==='ranged'){const r0=.07,p0=point(0,-r0),p1=point(l,-r0),p2=point(l,r0),p3=point(0,r0);prismMesh(out,[p0,p1,p2,p3],.84,.98,[...color,.55*pulse]);}
